      if(!l||lesson.contentKind!=='exercise'||l.preparationReview||(l.contentReview?.id??null)!==r.review||instructionFingerprint(lesson)!==r.fingerprint)continue;
      const previousInstruction=JSON.parse(JSON.stringify({description:lesson.description,guide:lesson.guide,learning:l})),previousAssessmentFingerprint=Assessment.pianoSignature(lesson),previousRhythm=JSON.parse(JSON.stringify(lesson.rhythm));
