  function reviewRightReleaseAndBlackGroups(lessons,adapter){
    let changed=0;
    const release=lessons.find(l=>l.id==='detail-p-release-01'),rl=release?.learning,sourceFingerprint='b7082afc';
    if(rl&&release.contentKind==='exercise'&&!rl.preparationReview&&rl.contentReview?.id==='early-release-v1'&&instructionFingerprint(release)===sourceFingerprint){
      const previousInstruction=JSON.parse(JSON.stringify({description:release.description,guide:release.guide,learning:rl})),previousAssessmentFingerprint=Assessment.pianoSignature(release);
      rl.requires=['course01-01'];rl.nextLessonId='detail-p-release-03';
      release.guide=adapter.normalizeGuide({...release.guide,setup:'Сначала найди C4 в уроке «Правая: найди C4 / До». Стопы устойчивы, плечи свободны, педаль выключена. Поставь правый большой 1 на C4; левая отдыхает. Здесь добавляем отдельное управление окончанием знакомого звука.'});
      rl.practiceSteps[0]='Подготовка: повтори «Правая: найди C4 / До», затем оставь большой палец 1 у той же C4. Послушай четыре раздельных звука одной высоты и представь короткую тишину между ними. Левая рука отдыхает.';
      rl.practiceSteps[1]='Медленно проверь одно нажатие и отпускание большого пальца, затем четыре C4 на «раз, два, три, четыре» при 56 BPM. Каждое звучание занимает 0,65 доли, просвет до следующего — 0,35. Не оставляй клавишу удержанной до следующей атаки и не обрывай её мгновенно; запястье и большой палец свободны.';
      rl.selfCheck[rl.selfCheck.length-1]='Следующий шаг — «Правая: две ноты с просветом», подготовленная смена C4–D4 пальцами 1–2.';
      rl.provenance.sourceNote+=' Подготовка этой редакции ссылается на правую C4; первоначальная левая пара сохраняется в истории инструкции. Счёт, ноты, пальцы и музыкальный зачёт текущей версии не меняются.';
      rl.preparationReview={id:'right-release-black-groups-v1',sourceFingerprint,previousAssessmentFingerprint,previousInstruction,reviewedFingerprint:instructionFingerprint(release)};changed++;
    }
    for(const r of rightBlackReviews){
      const lesson=lessons.find(l=>l.id===r.id),l=lesson?.learning;
      if(!l||lesson.contentKind!=='exercise'||l.preparationReview||l.contentReview||instructionFingerprint(lesson)!==r.fingerprint)continue;
      const previousInstruction=JSON.parse(JSON.stringify({description:lesson.description,guide:lesson.guide,learning:l})),previousAssessmentFingerprint=Assessment.pianoSignature(lesson),pair=r.id==='detail-p-black-01',flat=r.id==='detail-p-black-04';
      lesson.description=r.goal;l.goal=r.goal;l.requires=[...r.requires];l.coverageDomain='positions';l.nextLessonId=r.next;
      lesson.guide=adapter.normalizeGuide({stage:pair?'Правая рука: пара чёрных':'Группа трёх чёрных и смена направления',setup:'Стопы устойчивы, плечи свободны, педаль выключена. '+r.position,motion:r.motion,blind:'Сначала посмотри, подготовь положение и послушай образец. '+r.hearing+' После уверенного разбора повтори без подсказок; при потере опоры остановись и спокойно найди её снова.',mastery:'Верные отдельные вступления, заданные окончания и свободная подготовленная рука. Три чистые MIDI-попытки, одна из памяти; ещё одна после перерыва. '+r.hearing+' Номера пальцев и удобство проверяются у инструмента: MIDI их не определяет.'});
      l.practiceSteps=[
        'Подготовка: '+r.position+' Назови опоры и пальцы, послушай и заранее представь фразу. '+r.hearing,
        'Сначала разбери два соседних звука, затем обратное движение; после остановки соедини исходный рисунок. '+r.motion+' Вступления идут через одну долю при 56 BPM; считай «раз, два, три, четыре»'+(pair?'.':' и затем «раз» нового такта.')+' Каждый звук занимает 0,85 доли, просвет до следующего — 0,15. Последний заканчивается через '+(pair?'3,85':'4,85')+' доли от начала; конечная тишина отдельно не оценивается.',
        'Блок около 3–5 минут с остановками для самопроверки. После попытки отдельно проверь перенос: '+r.transfer+' Сохрани знакомые пульс, подготовленную руку и окончания. Это самостоятельная проба у инструмента, не текущая MIDI-последовательность и не новый урок. Вернись к исходной фразе после перерыва. '+r.nextText
      ];
      l.selfCheck=['Рука, регистр и пальцы соответствуют подготовке. Не подменяй движение другой рукой и не добавляй белые клавиши между чёрными.','Каждый звук получает своё нажатие и заканчивается перед следующим; тишина не ускоряет пульс.','Не зажимай кисть и не тяни пальцы из прежнего положения. При неудобстве остановись и проверь положение руки. '+r.hearing,'Образец развивает слуховое представление известной фразы; это не независимый тест слуха. Пальцы и художественное качество не подтверждаются MIDI.',r.nextText];
      l.rhythmNotice='Техническое упражнение проекта: '+(pair?'четыре':'пять')+' вступлений через одну долю, 56 BPM, звучание 0,85 и просвет 0,15 доли. Обычный профиль, без специального legato/staccato. Это короткая позиционная фигура, не полная гамма. Высоты, пальцы, исходный ритм, музыкальная версия и её зачёт сохранены. Допуски выбраны проектом.';
      l.references=[POSITION_CONTEXT,TECHNIQUE,PRACTICE];l.referenceTitles={[POSITION_CONTEXT]:'Jerry Kovarsky: нумерация и планирование позиции',[TECHNIQUE]:'Diana Dumlavwalla: форма руки и гибкое запястье',[PRACTICE]:'Bob Duke и Amy Simmons: небольшая цель практики'};l.sourceEvidenceIds=['kovarsky-fingering-context-2026-11-05','dumlavwalla-basic-technique-2026-11-05','duke-simmons-small-goals-2026-11-05'];
      l.provenance={type:'project-technical-drill',author:'Упражнение проекта',purpose:r.purpose,context:'Чёрные клавиши образуют удобные зрительные и осязательные группы для новых позиций и тональностей. Здесь изучается короткое подготовленное движение; перенос и полные гаммы требуют своих этапов.',sourceNote:'Ноты, регистр, конкретные пальцы, последовательность, 56 BPM и длительности выбраны проектом. Kovarsky, The Basics и Scenario One, подтверждает нумерацию и предварительный выбор подходящей позиции; Dumlavwalla, Inconsistent Hand Shape, — поддержанную руку и гибкое запястье. Источники не предписывают эти точные упражнения и допуски, не утверждают их педагогическую или физическую проверку.'};
      if(flat){l.pitchSpelling='flat-alias-v1';l.references.push(ENHARMONIC);l.referenceTitles[ENHARMONIC]='Robert Hutchinson: §1.5, разные названия одной клавиши';l.sourceEvidenceIds.push('hutchinson-enharmonic-2026-11-05');l.provenance.sourceNote+=' Hutchinson, §1.5 и абзац после Figure 1.5.1, перечисляет F♯=G♭, G♯=A♭, A♯=B♭ на фортепиано. В данном регистре это MIDI 54/56/58; написание и текущая подпись клавиши различаются, высоты не меняются.';}
      l.preparationReview={id:'right-release-black-groups-v1',sourceFingerprint:r.fingerprint,previousAssessmentFingerprint,previousInstruction,reviewedFingerprint:instructionFingerprint(lesson)};changed++;
    }
    return changed;
  }
