    for(const spec of minorPiano){if(existing.has(spec.id))continue;const lesson=lessons.find(l=>l.id===spec.id),learning=lesson.learning;
      learning.coverageDomain='triads';
      learning.practiceSteps=['Послушай образец; назови корень, терцию и квинту.','Спокойно найди позицию и пальцы; сыграй отдельные звуки и заданные созвучия со счётом.','Услышь разницу, затем повтори короткое задание из памяти и вернись к нему после перерыва.'];
      learning.selfCheck=[...spec.errors,'Сравнение выполняется на слух самостоятельно; известная последовательность не является независимым тестом слуха.'];
      learning.references=[THEORY,PRACTICE];learning.referenceTitles={[THEORY]:'The Open University: строение трезвучий',[PRACTICE]:'Bob Duke и Amy Simmons: короткая практика'};
      learning.provenance={type:'project-technical-drill',author:'Упражнение проекта',purpose:spec.purpose,context:'Подготовка к минорным аккордам и сопровождению. В классической и свободной игре важно узнавать состав аккорда и заранее готовить его форму.',sourceNote:'Музыкальная последовательность создана для этого урока. OpenLearn, раздел 7, подтверждает строение трезвучий; темп, пальцы и последовательность заданы проектом. Это не цитата из пьесы и не упражнение, приписанное известному исполнителю.'};
      learning.sourceEvidenceIds=['ou-triads-2026-11-05','duke-simmons-small-goals-2026-11-05'];
    }
    for(const spec of legatoPairs)if(!existing.has(spec.id))describeLegatoPair(lessons.find(l=>l.id===spec.id),spec,adapter);
